static PyObject *
_fast_vec_string_isalpha(PyArrayObject* char_array, PyArray_Descr* type)
{
    PyArrayIterObject* in_iter = NULL;
    PyArrayObject* result = NULL;
    PyArrayIterObject* out_iter = NULL;

    in_iter = (PyArrayIterObject*)PyArray_IterNew((PyObject*)char_array);
    if (in_iter == NULL) {
        goto err;
    }

    result = (PyArrayObject*)PyArray_SimpleNewFromDescr(
            PyArray_NDIM(char_array), PyArray_DIMS(char_array), type);
    if (result == NULL) {
        goto err;
    }

    out_iter = (PyArrayIterObject*)PyArray_IterNew((PyObject*)result);
    if (out_iter == NULL) {
        goto err;
    }

    int is_unicode = (PyArray_TYPE(char_array) == NPY_UNICODE);
    npy_intp itemsize = PyArray_ITEMSIZE(char_array);
    npy_intp num_chars = is_unicode ? (itemsize >> 2) : itemsize;

    while (PyArray_ITER_NOTDONE(in_iter)) {
        char* data = in_iter->dataptr;
        npy_bool is_alpha = 1;
        npy_intp i;
        npy_intp len = 0;

        if (is_unicode) {
            Py_UCS4* udata = (Py_UCS4*)data;
            for (i = 0; i < num_chars; i++) {
                if (udata[i] == 0) {
                    break;
                }
                len++;
                if (!Py_UNICODE_ISALPHA(udata[i])) {
                    is_alpha = 0;
                    break;
                }
            }
        } else {
            for (i = 0; i < num_chars; i++) {
                if (data[i] == 0) {
                    break;
                }
                len++;
                if (!NumPyOS_ascii_isalpha(data[i])) {
                    is_alpha = 0;
                    break;
                }
            }
        }
        if (len == 0) is_alpha = 0;

        *((npy_bool*)out_iter->dataptr) = is_alpha;

        PyArray_ITER_NEXT(in_iter);
        PyArray_ITER_NEXT(out_iter);
    }

    Py_DECREF(in_iter);
    Py_DECREF(out_iter);
    return (PyObject*)result;

err:
    Py_XDECREF(in_iter);
